#include <bits/stdc++.h>
using namespace std;

vector<int> arr(100);
int dp[100];

int LIS(int i)
{
    if(dp[i] != -1)
        return dp[i];

    int size = 1;

    for(int j = 0; j < i; j++)
    {
        if(arr[i] > arr[j])
        {
            size = max(size, LIS(j) + 1);
        }
    }

    return dp[i] = size;
}

void print_lis(int i)
{
    for(int j = 0; j < i; j++)
    {
        if(arr[i] > arr[j] && dp[j] + 1 == dp[i])
        {
            print_lis(j);
            break;
        }
    }

    cout << arr[i] << " ";
}

int main()
{
    memset(dp, -1, sizeof(dp));

    int n;
    cin >> n;

    for(int i = 0; i < n; i++)
    {
        cin >> arr[i];
    }

    int size = 0;
    int best_idx = 0;

    for(int i = 0; i < n; i++)
    {
        if(LIS(i) > size)
        {
            size = LIS(i);
            best_idx = i;
        }
    }

    cout << size << endl;

    print_lis(best_idx);
    cout << endl;

    return 0;
}

